package net.muxigame.console.runtime;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import net.muxigame.console.client.RuntimeFiles;
import net.muxigame.console.domain.*;

/** Integration test of final packaged RuntimeFiles -> actual isolated cores; never starts Minecraft. */
public final class MediaLaunchSmoke {
    private static int checks;private static final Gson JSON=new GsonBuilder().setPrettyPrinting().create();
    private static void check(boolean result,String label){checks++;if(!result)throw new AssertionError(label);}
    private static String crc(AvFrame frame){CRC32 crc=new CRC32();crc.update(frame.rgba());return Long.toHexString(crc.getValue());}
    private static void frame(Path output,AvFrame frame)throws IOException{BufferedImage image=new BufferedImage(frame.width(),frame.height(),BufferedImage.TYPE_INT_RGB);byte[] rgba=frame.rgba();for(int y=0;y<frame.height();y++)for(int x=0;x<frame.width();x++){int i=(y*frame.width()+x)*4;image.setRGB(x,y,(rgba[i]&255)<<16|(rgba[i+1]&255)<<8|(rgba[i+2]&255));}ImageIO.write(image,"PNG",output.toFile());}
    private static JsonObject manifest(String path)throws IOException{try(InputStream in=RuntimeFiles.class.getResourceAsStream(path)){if(in==null)throw new IOException("Missing final artifact manifest "+path);return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();}}
    private static void verifyFile(Path path,Path root,JsonObject hashes,JsonObject sizes)throws IOException{String name=root.relativize(path).toString().replace('\\','/');check(hashes.has(name)&&sizes.has(name),"selected file is in both packaged manifests");check(Files.size(path)==sizes.get(name).getAsLong(),"selected extracted byte count");check(Hashing.sha256(path).equals(hashes.get(name).getAsString()),"selected extracted SHA256");}
    private static void closed(ProcessConsoleRuntime runtime){check(!runtime.isAlive(),"owned worker exited");check(runtime.exitCode().orElse(-1)==0&&!runtime.wasForcedShutdown(),"owned worker normal exit 0");check(runtime.nativeTemporaryFilesCleaned(),"owned JNA/LWJGL temporary files cleaned");}
    private static int channel(AvFrame frame,int quarter,int color){return frame.rgba()[((frame.height()*quarter/4)*frame.width()+frame.width()/2)*4+color]&255;}
    private static JsonObject identity(Path file)throws IOException{JsonObject j=new JsonObject();j.addProperty("file",file.getFileName().toString());j.addProperty("bytes",Files.size(file));j.addProperty("sha256",Hashing.sha256(file));return j;}
    public static void main(String[] args)throws Exception{
        Path output=Path.of(args[0]).toAbsolutePath().normalize(),game=output.resolve("game"),inputs=output.resolve("inputs");Files.createDirectories(game);RuntimeFiles files=new RuntimeFiles(game);JsonObject hashes=manifest("/META-INF/muxi/extract-hashes.json"),sizes=manifest("/META-INF/muxi/extract-sizes.json");JsonArray results=new JsonArray();
        if(args.length>2){Path artifact=Path.of(args[2]).toRealPath();check(Path.of(RuntimeFiles.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath().equals(artifact),"RuntimeFiles loaded from the exact final artifact");check(Path.of(ProcessConsoleRuntime.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath().equals(artifact),"worker frontend loaded from exact final artifact");try(ZipFile zip=new ZipFile(artifact.toFile())){check(zip.stream().noneMatch(e->e.getName().endsWith("/lynxboot.img")||e.getName().endsWith("/disksys.rom")),"diagnostic firmware is not bundled in product artifact");}}
        Path pong=inputs.resolve("pong.zip");try(ZipOutputStream ignored=new ZipOutputStream(Files.newOutputStream(pong,StandardOpenOption.CREATE_NEW))){}Path bundle=inputs.resolve("pong.mxarc");ArcadeBundle.pack(pong,List.of(),bundle);check(new RomInspector().inspect(bundle,Platform.ARCADE).detection().equals("mxarc-1:pong"),"actual Pong envelope admitted");
        List<Platform> requested=args.length>1?Arrays.stream(args[1].split(",")).map(Platform::fromId).toList():List.of(Platform.ARCADE,Platform.N64,Platform.FDS);
        for(Platform platform:requested){
            Path content=switch(platform){case ARCADE->bundle;case N64->inputs.resolve("original-vi.z64");case FDS->inputs.resolve("original-transfer.fds");case LYNX->inputs.resolve("original.o");default->throw new AssertionError();};
            RomDescriptor admitted=new RomInspector().inspect(content,platform);RuntimeFiles.Selected selected=files.select(platform,content,UUID.nameUUIDFromBytes(platform.id().getBytes(StandardCharsets.US_ASCII)));LaunchConfig config=selected.launch();Path root=game.resolve("natives/muxi-console");verifyFile(config.core(),root,hashes,sizes);for(Path dependency:config.classpath())verifyFile(dependency,root,hashes,sizes);
            if(platform==Platform.ARCADE){check(config.content().getFileName().toString().equals("pong.zip"),"MAME receives actual driver basename");check(config.core().getFileName().toString().startsWith("mame"),"current MAME selected");check(Files.size(config.core())>64L*1024*1024,"large MAME extraction has no obsolete 64 MiB cap");}
            if(platform==Platform.N64){check(config.classpath().size()==8,"N64 worker has runtime/JNA/six GL dependencies");check(config.options().get("mupen64plus-rdp-plugin").equals("gliden64")&&config.options().get("mupen64plus-rsp-plugin").equals("hle")&&config.options().get("mupen64plus-cpucore").equals("pure_interpreter"),"fixed deterministic N64 backend options");}
            if(platform==Platform.FDS){check(Files.size(config.systemDirectory().resolve("disksys.rom"))==8192,"original diagnostic firmware outside artifact");Path firmware=config.systemDirectory().resolve("disksys.rom"),held=firmware.resolveSibling("diagnostic-firmware-held.tmp");Files.move(firmware,held);try{try{files.select(platform,content,UUID.randomUUID());throw new AssertionError("Missing FDS firmware accepted");}catch(IOException expected){checks++;}}finally{Files.move(held,firmware);}}
            if(platform==Platform.LYNX){check(admitted.detection().equals("lynx-bs93-size-and-entry"),"actual .o passes BS93 admission");Path firmware=config.systemDirectory().resolve("lynxboot.img"),held=firmware.resolveSibling("diagnostic-lynx-held.tmp");check(Files.size(firmware)==512,"original diagnostic-only 512-byte firmware");Files.move(firmware,held);try{try{files.select(platform,content,UUID.randomUUID());throw new AssertionError("Missing Lynx firmware accepted");}catch(IOException expected){checks++;}Files.write(firmware,new byte[511],StandardOpenOption.CREATE_NEW);try{files.select(platform,content,UUID.randomUUID());throw new AssertionError("Wrong Lynx firmware size accepted");}catch(IOException expected){checks++;}Files.delete(firmware);}finally{Files.move(held,firmware);}check(!selected.fingerprint().equals(Hashing.sha256(config.core())),"Lynx fingerprint includes firmware identity");}
            JsonObject result=new JsonObject();result.addProperty("platform",platform.id());result.addProperty("fingerprint",selected.fingerprint());result.addProperty("content",config.content().toString());result.addProperty("contentSha256",Hashing.sha256(config.content()));result.addProperty("admittedContent",content.toString());result.addProperty("admittedContentSha256",admitted.sha256());result.addProperty("detection",admitted.detection());result.addProperty("coreSha256",Hashing.sha256(config.core()));result.addProperty("coreBytes",Files.size(config.core()));result.addProperty("classpathCount",config.classpath().size());JsonArray dependencies=new JsonArray();for(Path dependency:config.classpath())dependencies.add(identity(dependency));result.add("classpath",dependencies);if(platform==Platform.LYNX||platform==Platform.FDS)result.add("diagnosticFirmware",identity(config.systemDirectory().resolve(platform==Platform.LYNX?"lynxboot.img":"disksys.rom")));byte[] state;AvFrame expected;
            ProcessConsoleRuntime runtime=ProcessConsoleRuntime.open(config);result.addProperty("firstPid",runtime.workerPid());
            try(runtime){
                check(runtime.isAlive()&&runtime.workerPid()!=ProcessHandle.current().pid(),"actual isolated live core");AvFrame image=null;for(int i=0;i<120;i++)image=runtime.step(InputFrame.idle());
                check(image!=null&&image.width()>0&&image.height()>0,"actual game pixels");Set<Integer> colors=new HashSet<>();for(int i=0;i<image.rgba().length;i+=4)colors.add((image.rgba()[i]&255)<<16|(image.rgba()[i+1]&255)<<8|(image.rgba()[i+2]&255));check(colors.size()>1,"nonuniform executed diagnostic");
                if(platform==Platform.LYNX){check(image.width()==160&&image.height()==102,"actual Lynx LCD dimensions");check(channel(image,1,0)>180&&channel(image,1,1)<80,"BS93 Mikey LCD upper half red");check(channel(image,3,0)<40&&channel(image,3,1)<40,"BS93 Mikey LCD lower half dark");}
                if(platform==Platform.N64){check(channel(image,1,0)>180&&channel(image,1,2)<40&&channel(image,3,2)>180&&channel(image,3,0)<40,"actual N64 VI red and blue bands");}
                check(Double.isFinite(image.displayAspect())&&image.displayAspect()>0,"MXCWv2 carries native display aspect");result.addProperty("displayAspect",image.displayAspect());result.addProperty("width",image.width());result.addProperty("height",image.height());result.addProperty("colors",colors.size());result.addProperty("frameCrc",crc(image));frame(output.resolve(platform.id()+"-frame.png"),image);
                state=runtime.saveState();check(state.length>16,"actual native save state");expected=null;for(int i=0;i<5;i++)expected=runtime.step(InputFrame.idle());
            }closed(runtime);
            ProcessConsoleRuntime reopened=ProcessConsoleRuntime.open(config);result.addProperty("secondPid",reopened.workerPid());
            try(reopened){
                // This is deliberately the fresh-worker load-before-first-step path used by the actual client.
                reopened.loadState(state);AvFrame restored=null;for(int i=0;i<5;i++)restored=reopened.step(InputFrame.idle());check(restored!=null&&reopened.isAlive(),"actual fresh-process load-before-step and resumed frame");
                result.addProperty("stateBytes",state.length);result.addProperty("stateSha256",Hashing.sha256(state));result.addProperty("restoredCrc",crc(restored));result.addProperty("continuationCrc",crc(expected));boolean equal=crc(expected).equals(crc(restored));result.addProperty("pixelContinuationEqual",equal);frame(output.resolve(platform.id()+"-restored.png"),restored);
                if(platform==Platform.LYNX||platform==Platform.FDS)check(equal,"software diagnostic retains native pixel state across processes");
            }closed(reopened);result.addProperty("normalExit",true);result.addProperty("forcedShutdown",false);result.addProperty("nativeTemporaryFilesCleaned",true);results.add(result);Files.writeString(output.resolve("partial-result.json"),JSON.toJson(results),StandardCharsets.UTF_8);System.out.println(platform.id()+" real RuntimeFiles launch/save/load calls passed; pixelContinuationEqual="+result.get("pixelContinuationEqual"));
        }
        JsonObject report=new JsonObject();report.addProperty("checks",checks);report.addProperty("allWorkersClosed",true);report.add("platforms",results);Files.writeString(output.resolve("result.json"),JSON.toJson(report),StandardCharsets.UTF_8);System.out.println("MediaLaunchSmoke: "+checks+" passed");
    }
}
